def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    wall = min(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == wall or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            touches_edge = False
            sides = set()
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y == 0:
                    touches_edge = True
                    sides.add('top')
                if y == h - 1:
                    touches_edge = True
                    sides.add('bottom')
                if x == 0:
                    touches_edge = True
                    sides.add('left')
                if x == w - 1:
                    touches_edge = True
                    sides.add('right')
                for dy, dx, side in ((1, 0, 'bottom'), (-1, 0, 'top'),
                                     (0, 1, 'right'), (0, -1, 'left')):
                    ny, nx = y + dy, x + dx
                    if not (0 <= ny < h and 0 <= nx < w):
                        continue
                    if grid[ny][nx] == wall:
                        sides.add(side)
                    elif (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            # A region is enclosed when its boundary is formed by wall and/or
            # the canvas edge on all four directions.
            enclosed = all(s in sides for s in ('top', 'bottom', 'left', 'right'))
            if enclosed:
                for y, x in comp:
                    out[y][x] = 4
    return out
